class Solution {
    public int[] runningSum(int[] nums) {
        for (int i = 1; i < nums.length; i++) {
            nums[i] += nums[i - 1];
        }
        return nums;
    }
}

class Solution {
    public int[] runningSum(int[] nums) {
        int[] answer = new int[nums.length];
        int running = 0;
        for (int i = 0; i < nums.length; i++) {
            running += nums[i];
            answer[i] = running;
        }
        return answer;
    }
}

class Solution {
    public int[] runningSum(int[] nums) {
        int[] answer = nums.clone();
        fill(answer, 1);
        return answer;
    }

    private void fill(int[] answer, int index) {
        if (index == answer.length) {
            return;
        }
        answer[index] += answer[index - 1];
        fill(answer, index + 1);
    }
}

class Solution {
    public int[] runningSum(int[] nums) {
        int[] answer = nums.clone();
        for (int step = 1; step < answer.length; step <<= 1) {
            int[] previous = answer.clone();
            for (int i = step; i < answer.length; i++) {
                answer[i] = previous[i] + previous[i - step];
            }
        }
        return answer;
    }
}
